import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;

        // Marca as pessoas que foram infectadas por outra pessoa (aparecem como Xi em alguma cadeia)
        boolean[] infectedBySomeone = new boolean[n + 1];

        for (int i = 0; i < c; i++) {
            in.nextToken(); // P (infectante) - nao precisa marcar
            in.nextToken(); // I (tamanho da cadeia)
            int k = (int) in.nval;
            for (int j = 0; j < k; j++) {
                in.nextToken();
                infectedBySomeone[(int) in.nval] = true;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (!infectedBySomeone[i]) {
                sb.append(i).append('\n');
            }
        }
        System.out.print(sb);
    }
}
